{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.json.JSONArray;
import org.json.JSONObject;
import org.joget.plugin.base.PluginManager;
import org.joget.workflow.model.service.WorkflowManager;

final String LOGGER = "IOC-BeanShell";
final String REQ_TBL = "app_fd_eth_ioc_item_request";
final String HV_REQ_ID = "#form.eth_ioc_item_request.id#";


String hv(String expr){
 try{
 String v = AppUtil.processHashVariable(expr, workflowAssignment, null, null);
 if (v == null) return null;
 v = v.trim();
 return (v.length()==0 || v.indexOf('#')>=0) ? null : v;
 }catch(Exception e){ return null; }
}
boolean blank(String s){ return s==null || s.trim().isEmpty() || "null".equalsIgnoreCase(s.trim()); }

/* ===== MAIN ===== */
Connection con=null; PreparedStatement ps=null; ResultSet rs=null;
try{
 String reqId = hv(HV_REQ_ID);
 if (reqId == null){
 LogUtil.warn(LOGGER, "Request ID not resolved.");
 // still clear the variable so UI doesn't show stale data
 PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
 WorkflowManager wm = (WorkflowManager) pm.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "merge_inputs_title", "");
 return "no-id";
 }

 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 ps = con.prepareStatement("SELECT c_addRawMaterialItem FROM " + REQ_TBL + " WHERE id=?");
 ps.setString(1, reqId);
 rs = ps.executeQuery();

 String itemsJson = null;
 if (rs.next()){
 itemsJson = rs.getString("c_addRawMaterialItem");
 } else {
 LogUtil.warn(LOGGER, "No request row found for id=" + reqId);
 }

 String mergedTitles = "";
 if (!blank(itemsJson)){
 try{
 JSONArray arr = new JSONArray(itemsJson);
 StringBuilder sb = new StringBuilder();
 for (int i=0; i<arr.length(); i++){
 JSONObject obj = arr.optJSONObject(i);
 if (obj == null) continue;
 String title = obj.optString("input_description", null);


 if (!blank(title)){
 if (sb.length() > 0) sb.append(", ");
 sb.append(title);
 }
 }
 mergedTitles = sb.toString();
 }catch(Exception je){
 LogUtil.warn(LOGGER, "Invalid JSON in c_addRawMaterialItem for id=" + reqId + ": " + je.getMessage());
 }
 } else {
 LogUtil.info(LOGGER, "Empty or null c_addRawMaterialItem for id=" + reqId);
 }

 try{
 PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
 WorkflowManager wm = (WorkflowManager) pm.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "merge_inputs_title", mergedTitles);
 LogUtil.info(LOGGER, "Set merge_inputs_title = " + mergedTitles);
 }catch(Exception wex){
 LogUtil.warn(LOGGER, "Failed to set workflow variable 'merge_inputs_title': " + wex.getMessage());
 }

 return "success";

}catch(Exception e){
 LogUtil.error(LOGGER, e, "FAILED: " + e.getMessage());
 try{
 PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
 WorkflowManager wm = (WorkflowManager) pm.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "merge_inputs_title", "");
 }catch(Exception ignore){}
 return "error";
}finally{
 try{ if(rs!=null) rs.close(); }catch(Exception ig){}
 try{ if(ps!=null) ps.close(); }catch(Exception ig){}
 try{ if(con!=null) con.close(); }catch(Exception ig){}
}
"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Types;
import java.sql.Timestamp;
import javax.sql.DataSource;
import java.io.BufferedReader;
import java.io.FileReader;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.service.FormDataService;
import org.joget.apps.form.model.FormData;
import org.joget.commons.util.LogUtil;

import java.io.BufferedReader;
import java.io.FileReader;

// Get the uploaded file path from process variable (from file upload form)
String uploadedFile = (String) workflow.getVariable("uploadedCsv");
String productFormId = "product";
String productTable = "app_fd_eth_ioc_products";

BufferedReader br = null;
Connection con = null;
PreparedStatement productSelectionQuery = null;
ResultSet productResultSet = null;

// Get the FormDataService
FormDataService formDataService = (FormDataService) appContext.getBean("formDataService");

try {
	br = new BufferedReader(new FileReader(uploadedFile));
 String line;
 int lineNum = 0;

 while ((line = br.readLine()) != null) {
 lineNum++;
 if(lineNum == 1) continue; // Skip header row

 // Split CSV columns (adjust delimiter if needed)
 String[] columns = line.split(";");

		String sectorId = columns[0];
		String sectorCode = columns[1];
		String productId = '';
		String productCode = columns[2];
		String productTitle = columns[3];
		String productHscode = columns[4];
		String productQuantity = columns[5];
		String productUom = columns[6];
		String productNote = columns[7];
		String rmtTitle = columns[8];
		String rmtCode = columns[9];
		String rmiCode = columns[10];
		String rmiTitle = columns[11];
		String rmiHscode = columns[12];
		String rmtUom = columns[13];
		String rmtWaste = columns[14];
		String rmtIoc = columns[15];

		// DB connection
		DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
		if (ds == null) { LogUtil.warn(LOGGER, "DataSource 'setupDataSource' not found."); return "no-datasource"; }
		con = ds.getConnection();
		if (con == null) { LogUtil.warn(LOGGER, "No DB connection."); return "no-connection"; }
		con.setAutoCommit(true);

		productSelectionQuery = con.prepareStatement(
		 "SELECT id " +
		 "FROM " + productTable + " WHERE c_product_code = ? LIMIT 1");
		productSelectionQuery.setString(1,productCode);
		productResultSet = productSelectionQuery.executeQuery();
		if (productResultSet.next()) {
			productId = productResultSet.getString("id");
		} else {
			// Map CSV columns to form fields
			java.util.Map<String, Object> dataMap = new java.util.HashMap<>();
			dataMap.put("sector", sectorId);
			dataMap.put("sector_code", sectorCode); 
			dataMap.put("product_code", productCode);
			dataMap.put("hscode", productHscode);
			dataMap.put("title", productTitle);
			dataMap.put("uom", productUom);
			dataMap.put("standard_quantity", productQuantity);
			dataMap.put("other_notes", productNote);
			// Add more fields as needed

			// Create FormData productFormId
			FormData fd = formDataService.createFormData(formId);
			fd.setFormDataMap(dataMap);

			// Save form record
			formDataService.saveOrUpdate(fd);
			productId = fd.getPrimaryKeyValue();

			productResultSet.close();
			productSelectionQuery.close();
		}
 }

 LogUtil.info("CSV Import", "CSV import completed successfully!");
} catch (Exception e) {
 LogUtil.error("CSV Import", "Error importing CSV: " + e.getMessage(), e);
} finally {
 try { if (productResultSet != null) productResultSet.close(); } catch (Exception e) {}
 try { if (productSelectionQuery != null) productSelectionQuery.close(); } catch (Exception e) {}
 try { if (con != null) con.close(); } catch (Exception e) {}
 try { if (br != null) br.close(); } catch (Exception e) {}
}"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.json.JSONArray;
import org.json.JSONObject;

// =================== CONFIG ===================
final String LOGGER = "IOC-BeanShell";
final String SRC_TAB = "app_fd_eth_ioc_application";
final String DST_TAB = "app_fd_eth_ioc_products";
final String SECT_TAB = "app_fd_eth_ioc_sector";
final String TYPE_TAB = "app_fd_eth_ioc_raw_mat_type";
final String ITEM_TAB = "app_fd_eth_ioc_raw_mat_item";
final String HV_ID = "#form.eth_ioc_application.id#"; // or #variable.recordId#

// =================== HELPERS ===================
String resolveHV(String hv) {
 try {
 String v = AppUtil.processHashVariable(hv, workflowAssignment, null, null);
 if (v == null) return null;
 v = v.trim();
 return (v.isEmpty() || v.indexOf('#') >= 0) ? null : v;
 } catch (Exception e) { return null; }
}
boolean isBlank(String s){ return s == null || s.trim().isEmpty(); }
void setNullableString(PreparedStatement ps, int i, String v) throws SQLException {
 if (v == null) ps.setNull(i, Types.VARCHAR); else ps.setString(i, v);
}
void verifyRow(Connection con, String id) {
 PreparedStatement v = null; ResultSet r = null;
 try {
 v = con.prepareStatement(
 "SELECT id, c_sector, c_sector_code, c_title, c_hscode, c_uom, c_standard_quantity, c_product_code " +
 "FROM " + DST_TAB + " WHERE id = ? LIMIT 1");
 v.setString(1, id);
 r = v.executeQuery();
 if (r.next()) {
 LogUtil.info(LOGGER, "CONFIRMED → id=" + r.getString("id")
 + ", sector=" + r.getString("c_sector")
 + ", sector_code=" + r.getString("c_sector_code")
 + ", title=" + r.getString("c_title")
 + ", hscode=" + r.getString("c_hscode")
 + ", uom=" + r.getString("c_uom")
 + ", std_qty=" + r.getString("c_standard_quantity")
 + ", product_code=" + r.getString("c_product_code"));
 } else {
 LogUtil.warn(LOGGER, "No row found after upsert for id=" + id);
 }
 } catch (Exception ex) {
 LogUtil.warn(LOGGER, "Verify failed for id=" + id + ": " + ex.getMessage());
 } finally {
 try { if (r != null) r.close(); } catch (Exception e) {}
 try { if (v != null) v.close(); } catch (Exception e) {}
 }
}

// =================== MAIN ===================
Connection con = null;
PreparedStatement sel = null;
PreparedStatement ins = null;
ResultSet rs = null;

try {
 // Resolve inputs
 String appId = resolveHV(HV_ID);
 if (appId == null) { LogUtil.warn(LOGGER, "App ID not resolved"); return "no-id"; }

 String currEmail = resolveHV("#currentUser.email#");
 String fn = resolveHV("#currentUser.firstName#");
 String ln = resolveHV("#currentUser.lastName#");
 String currFull = (isBlank(ln) && isBlank(fn)) ? null : ((isBlank(ln)?"":ln) + (isBlank(ln)||isBlank(fn)?"":" ") + (isBlank(fn)?"":fn));

 // DB connection
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 if (ds == null) { LogUtil.warn(LOGGER, "DataSource 'setupDataSource' not found."); return "no-datasource"; }
 con = ds.getConnection();
 if (con == null) { LogUtil.warn(LOGGER, "No DB connection."); return "no-connection"; }
 con.setAutoCommit(true);

 LogUtil.info(LOGGER, "START. Processing id=" + appId);

 // 1) Read parent row + sector code (STRICT: join by ID)
 sel = con.prepareStatement(
 "SELECT a.id, a.c_sector, a.c_hscode, a.c_requested__product, a.c_add_products, s.c_code AS sector_code " +
 "FROM " + SRC_TAB + " a " +
 "LEFT JOIN " + SECT_TAB + " s ON s.id = a.c_sector " +
 "WHERE a.id = ?"
 );
 sel.setString(1, appId);
 rs = sel.executeQuery();
 if (!rs.next()) { LogUtil.warn(LOGGER, "No source row for id=" + appId); return "not-found"; }

 String sectorId = rs.getString("c_sector"); // sector ID (as stored in application)
 String hscodeValue = rs.getString("c_hscode");
 String requestedProductValue = rs.getString("c_requested__product");
 String addProductsJson = rs.getString("c_add_products");
 String joinedSectorCode = rs.getString("sector_code"); // <-- comes from sector table
 String idValue = rs.getString("id");

 LogUtil.info(LOGGER, "Source OK: sectorId=" + sectorId + ", hs=" + hscodeValue + ", prod=" + requestedProductValue);
 LogUtil.info(LOGGER, "Joined sector_code = " + joinedSectorCode);

 // 2) Overlay from c_add_products (FIRST item only)
 String jsonUom = null, jsonStdQty = null, jsonHs = null, jsonCode = null, jsonTitle = null;
 Object rawTypesObj = null; // may be JSONArray or String
 if (!isBlank(addProductsJson)) {
 try {
 JSONArray arr = new JSONArray(addProductsJson);
 if (arr.length() > 0) {
 JSONObject first = arr.optJSONObject(0);
 if (first != null) {
 jsonUom = first.optString("uom", null);
 jsonStdQty = first.optString("standard_quantity", null);
 jsonHs = first.optString("hscode", null);
 jsonCode = first.optString("product_code", null);
 jsonTitle = first.optString("product", null);
 rawTypesObj = first.opt("raw_material_type"); // may be array or string
 }
 }
 } catch (Exception jex) {
 LogUtil.warn(LOGGER, "Invalid JSON in c_add_products for id=" + appId + ": " + jex.getMessage());
 }
 }

 // 3) Final values (JSON overrides)
 String outSector = sectorId; // keep the ID as stored
 String outSectorCode = (joinedSectorCode == null ? null : joinedSectorCode.trim());
 String outHscode = !isBlank(jsonHs) ? jsonHs : hscodeValue;
 String outTitle = !isBlank(jsonTitle) ? jsonTitle : requestedProductValue;
 String outUom = !isBlank(jsonUom) ? jsonUom : null;
 String outStdQty = !isBlank(jsonStdQty) ? jsonStdQty : null;
 String outProdCode = !isBlank(jsonCode) ? jsonCode : null;

 // c_product_code = c_sector_code + "-" + product_code (only if both exist), otherwise keep product_code
 String outProdCodeConcat = (!isBlank(outSectorCode) && !isBlank(outProdCode))
 ? (outSectorCode + "-" + outProdCode)
 : outProdCode;

 LogUtil.info(LOGGER, "Final values → sector_code=" + outSectorCode + ", product_code(in)=" + outProdCode + ", product_code(out)=" + outProdCodeConcat);

 // 4) Upsert into products (with audit)
 Timestamp now = new Timestamp(System.currentTimeMillis());
 ins = con.prepareStatement(
 "INSERT INTO " + DST_TAB + " " +
 " (id, c_sector, c_sector_code, c_hscode, c_title, c_uom, c_standard_quantity, c_product_code, " +
 " dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName) " +
 "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_sector=VALUES(c_sector), " +
 " c_sector_code=VALUES(c_sector_code), " +
 " c_hscode=VALUES(c_hscode), " +
 " c_title=VALUES(c_title), " +
 " c_uom=VALUES(c_uom), " +
 " c_standard_quantity=VALUES(c_standard_quantity), " +
 " c_product_code=VALUES(c_product_code), " +
 " dateModified=VALUES(dateModified), " +
 " modifiedBy=VALUES(modifiedBy), " +
 " modifiedByName=VALUES(modifiedByName)"
 );

 int i = 1;
 setNullableString(ins, i++, idValue); // id
 setNullableString(ins, i++, outSector); // c_sector (id)
 setNullableString(ins, i++, outSectorCode); // c_sector_code (from join)
 setNullableString(ins, i++, outHscode); // c_hscode
 setNullableString(ins, i++, outTitle); // c_title
 setNullableString(ins, i++, outUom); // c_uom
 setNullableString(ins, i++, outStdQty); // c_standard_quantity
 setNullableString(ins, i++, outProdCodeConcat); // c_product_code
 ins.setTimestamp(i++, now); // dateCreated
 ins.setTimestamp(i++, now); // dateModified
 setNullableString(ins, i++, currEmail); // createdBy
 setNullableString(ins, i++, (isBlank(ln)&&isBlank(fn)) ? null : ((isBlank(ln)?"":ln) + (isBlank(ln)||isBlank(fn)?"":" ") + (isBlank(fn)?"":fn))); // createdByName
 setNullableString(ins, i++, currEmail); // modifiedBy
 setNullableString(ins, i++, currFull); // modifiedByName

 int rows = ins.executeUpdate();
 LogUtil.info(LOGGER, "UPSERT complete. Affected rows=" + rows + " (0 can be 'no change').");
 try { ins.close(); } catch (Exception ignore) {}

 // 5) Verify product write
 verifyRow(con, idValue);

 // 6) ---- RAW MATERIALS (Types & Items) ----
 // Guard: only proceed if raw_material_type exists & is non-empty
 JSONArray rawTypes = null;
 try {
 if (rawTypesObj instanceof JSONArray) {
 rawTypes = (JSONArray) rawTypesObj;
 } else if (rawTypesObj instanceof String) {
 String s = (String) rawTypesObj;
 if (!isBlank(s)) rawTypes = new JSONArray(s);
 }
 } catch (Exception jx) {
 LogUtil.warn(LOGGER, "raw_material_type not a valid JSON array; skipping. Reason: " + jx.getMessage());
 }

 if (rawTypes == null || rawTypes.length() == 0) {
 LogUtil.info(LOGGER, "No raw_material_type to process. Done.");
 LogUtil.info(LOGGER, "END. SUCCESS for id=" + appId);
 return "success";
 }

 // Prepare UPSERTs once (good performance)
 String typeSQL =
 "INSERT INTO " + TYPE_TAB + " " +
 " (id, dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName," +
 " c_product_hscode, c_input_output_coefficient, c_product, c_uom, c_quantity, " +
 " c_raw_material_type_code, c_waste_percentage, c_product_code, c_title, c_sector) " +
 "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_input_output_coefficient=VALUES(c_input_output_coefficient)," +
 " c_uom=VALUES(c_uom), c_quantity=VALUES(c_quantity)," +
 " c_raw_material_type_code=VALUES(c_raw_material_type_code)," +
 " c_waste_percentage=VALUES(c_waste_percentage)," +
 " c_product_code=VALUES(c_product_code), c_title=VALUES(c_title)," +
 " c_sector=VALUES(c_sector), dateModified=VALUES(dateModified)," +
 " modifiedBy=VALUES(modifiedBy), modifiedByName=VALUES(modifiedByName)";
 PreparedStatement upType = con.prepareStatement(typeSQL);

 String itemSQL =
 "INSERT INTO " + ITEM_TAB + " " +
 " (id, dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName," +
 " c_product, c_raw_material_type, c_hscode, c_raw_material_type_code, c_title, c_sector, c_input_code) " +
 "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_hscode=VALUES(c_hscode), c_raw_material_type_code=VALUES(c_raw_material_type_code)," +
 " c_title=VALUES(c_title), c_sector=VALUES(c_sector), c_input_code=VALUES(c_input_code)," +
 " dateModified=VALUES(dateModified), modifiedBy=VALUES(modifiedBy), modifiedByName=VALUES(modifiedByName)";
 PreparedStatement upItem = con.prepareStatement(itemSQL);

 int typeUpserts = 0, itemUpserts = 0;

 for (int t = 0; t < rawTypes.length(); t++) {
 JSONObject tObj = rawTypes.optJSONObject(t);
 if (tObj == null) continue;

 String typeId = tObj.optString("RS_UNIQUE_VALUE", null);
 if (isBlank(typeId)) typeId = java.util.UUID.randomUUID().toString();

 String t_desc = tObj.optString("raw_material_type_description", null);
 String t_uom = tObj.optString("uom", null);
 String t_qty = tObj.optString("quantity", null);
 String t_ioc = tObj.optString("input_output_coefficient", null);
 String t_waste = tObj.optString("waste_percentage", null);
 String t_code = tObj.optString("raw_material_code", null);
 Object itemsObj = tObj.opt("raw_material_input"); // may be array or string

 // Upsert TYPE
 int a = 1;
 setNullableString(upType, a++, typeId);
 upType.setTimestamp(a++, now);
 upType.setTimestamp(a++, now);
 setNullableString(upType, a++, currEmail);
 setNullableString(upType, a++, (isBlank(ln)&&isBlank(fn)) ? null : (ln + (isBlank(fn)?"":" ") + fn));
 setNullableString(upType, a++, currEmail);
 setNullableString(upType, a++, currFull);
 setNullableString(upType, a++, outHscode); // c_product_hscode (product HS)
 setNullableString(upType, a++, t_ioc); // c_input_output_coefficient
 setNullableString(upType, a++, idValue); // c_product (FK → product/application id)
 setNullableString(upType, a++, t_uom); // c_uom
 setNullableString(upType, a++, t_qty); // c_quantity
 setNullableString(upType, a++, t_code); // c_raw_material_type_code
 setNullableString(upType, a++, t_waste); // c_waste_percentage
 setNullableString(upType, a++, outProdCodeConcat); // c_product_code (e.g., ELE-53)
 setNullableString(upType, a++, t_desc); // c_title
 setNullableString(upType, a++, outSector); // c_sector (store sector id)
 typeUpserts += upType.executeUpdate();

 // Parse items array (defensive)
 JSONArray itemsArr = null;
 try {
 if (itemsObj instanceof JSONArray) {
 itemsArr = (JSONArray) itemsObj;
 } else if (itemsObj instanceof String) {
 String s = (String) itemsObj;
 if (!isBlank(s)) itemsArr = new JSONArray(s);
 }
 } catch (Exception jx) {
 LogUtil.warn(LOGGER, "raw_material_input invalid for typeId=" + typeId + ": " + jx.getMessage());
 }

 if (itemsArr == null || itemsArr.length() == 0) continue;

 for (int k = 0; k < itemsArr.length(); k++) {
 JSONObject it = itemsArr.optJSONObject(k);
 if (it == null) continue;

 String itemId = it.optString("RS_UNIQUE_VALUE", null);
 if (isBlank(itemId)) itemId = java.util.UUID.randomUUID().toString();

 String i_desc = it.optString("input_description", null);
 String i_code = it.optString("input_code", null);
 String i_hs = it.optString("hscode", null);

 int b = 1;
 setNullableString(upItem, b++, itemId);
 upItem.setTimestamp(b++, now);
 upItem.setTimestamp(b++, now);
 setNullableString(upItem, b++, currEmail);
 setNullableString(upItem, b++, (isBlank(ln)&&isBlank(fn)) ? null : (ln + (isBlank(fn)?"":" ") + fn));
 setNullableString(upItem, b++, currEmail);
 setNullableString(upItem, b++, currFull);
 setNullableString(upItem, b++, idValue); // c_product (FK → product/application id)
 setNullableString(upItem, b++, typeId); // c_raw_material_type (FK → type)
 setNullableString(upItem, b++, i_hs); // c_hscode
 setNullableString(upItem, b++, t_code); // c_raw_material_type_code (carry from type)
 setNullableString(upItem, b++, i_desc); // c_title
 setNullableString(upItem, b++, outSector); // c_sector
 setNullableString(upItem, b++, i_code); // c_input_code
 itemUpserts += upItem.executeUpdate();
 }
 }

 try { upType.close(); } catch (Exception ignore) {}
 try { upItem.close(); } catch (Exception ignore) {}

 LogUtil.info(LOGGER, "RAW MATERIALS written. types=" + typeUpserts + ", items=" + itemUpserts);

 LogUtil.info(LOGGER, "END. SUCCESS for id=" + appId);
 return "success";

} catch (Exception e) {
 LogUtil.error(LOGGER, e, "FAILED: " + e.getMessage());
 return "error";
} finally {
 try { if (rs != null) rs.close(); } catch (Exception ex) {}
 try { if (sel != null) sel.close(); } catch (Exception ex) {}
 try { if (ins != null) sel.close(); } catch (Exception ex) {}
 try { if (con != null) con.close(); } catch (Exception ex) {}
}
































