{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.json.JSONArray;
import org.json.JSONObject;

// =================== CONFIG ===================
final String LOGGER = "IOC-BeanShell";
final String SRC_TAB = "app_fd_eth_ioc_application";
final String DST_TAB = "app_fd_eth_ioc_products";
final String SECT_TAB = "app_fd_eth_ioc_sector";
final String TYPE_TAB = "app_fd_eth_ioc_raw_mat_type"; // <-- back in use
final String ITEM_TAB = "app_fd_eth_ioc_raw_mat_item";
final String HV_ID = "#form.eth_ioc_application.id#"; // or #variable.recordId#

// =================== HELPERS ===================
String resolveHV(String hv) {
 try {
 String v = AppUtil.processHashVariable(hv, workflowAssignment, null, null);
 if (v == null) return null;
 v = v.trim();
 return (v.isEmpty() || v.indexOf('#') >= 0) ? null : v;
 } catch (Exception e) { return null; }
}
boolean isBlank(String s){ return s == null || s.trim().isEmpty() || "null".equalsIgnoreCase(s.trim()); }
void setNullableString(PreparedStatement ps, int i, String v) throws SQLException {
 if (v == null) ps.setNull(i, Types.VARCHAR); else ps.setString(i, v);
}
void verifyRow(Connection con, String id) {
 PreparedStatement v = null; ResultSet r = null;
 try {
 v = con.prepareStatement(
 "SELECT id, c_sector, c_sector_code, c_title, c_hscode, c_uom, c_standard_quantity, c_product_code " +
 "FROM " + DST_TAB + " WHERE id = ? LIMIT 1");
 v.setString(1, id);
 r = v.executeQuery();
 if (r.next()) {
 LogUtil.info(LOGGER, "CONFIRMED → id=" + r.getString("id")
 + ", sector=" + r.getString("c_sector")
 + ", sector_code=" + r.getString("c_sector_code")
 + ", title=" + r.getString("c_title")
 + ", hscode=" + r.getString("c_hscode")
 + ", uom=" + r.getString("c_uom")
 + ", std_qty=" + r.getString("c_standard_quantity")
 + ", product_code=" + r.getString("c_product_code"));
 } else {
 LogUtil.warn(LOGGER, "No row found after upsert for id=" + id);
 }
 } catch (Exception ex) {
 LogUtil.warn(LOGGER, "Verify failed for id=" + id + ": " + ex.getMessage());
 } finally {
 try { if (r != null) r.close(); } catch (Exception e) {}
 try { if (v != null) v.close(); } catch (Exception e) {}
 }
}

// =================== MAIN ===================
Connection con = null;
PreparedStatement sel = null;
PreparedStatement ins = null;
PreparedStatement upType = null;
PreparedStatement upItem = null;
ResultSet rs = null;

try {
 // Resolve inputs
 String appId = resolveHV(HV_ID);
 if (appId == null) { LogUtil.warn(LOGGER, "App ID not resolved"); return "no-id"; }

 String currEmail = resolveHV("#currentUser.email#");
 String fn = resolveHV("#currentUser.firstName#");
 String ln = resolveHV("#currentUser.lastName#");
 String currFull = (isBlank(ln) && isBlank(fn)) ? null : ((isBlank(ln)?"":ln) + (isBlank(ln)||isBlank(fn)?"":" ") + (isBlank(fn)?"":fn));

 // DB connection
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 if (ds == null) { LogUtil.warn(LOGGER, "DataSource 'setupDataSource' not found."); return "no-datasource"; }
 con = ds.getConnection();
 if (con == null) { LogUtil.warn(LOGGER, "No DB connection."); return "no-connection"; }
 con.setAutoCommit(true);

 LogUtil.info(LOGGER, "START. Processing id=" + appId);

 // 1) Read parent row + sector code (STRICT: join by ID)
 sel = con.prepareStatement(
 "SELECT a.id, a.c_sector, a.c_hscode, a.c_requested__product, a.c_add_products, s.c_code AS sector_code " +
 "FROM " + SRC_TAB + " a " +
 "LEFT JOIN " + SECT_TAB + " s ON s.id = a.c_sector " +
 "WHERE a.id = ?"
 );
 sel.setString(1, appId);
 rs = sel.executeQuery();
 if (!rs.next()) { LogUtil.warn(LOGGER, "No source row for id=" + appId); return "not-found"; }

 String sectorId = rs.getString("c_sector");
 String hscodeValue = rs.getString("c_hscode");
 String requestedProductValue = rs.getString("c_requested__product");
 String addProductsJson = rs.getString("c_add_products");
 String joinedSectorCode = rs.getString("sector_code");
 String idValue = rs.getString("id");

 LogUtil.info(LOGGER, "Source OK: sectorId=" + sectorId + ", hs=" + hscodeValue + ", prod=" + requestedProductValue);
 LogUtil.info(LOGGER, "Joined sector_code = " + joinedSectorCode);

 // 2) Overlay from c_add_products (FIRST item only)
 String jsonUom = null, jsonStdQty = null, jsonHs = null, jsonCode = null, jsonTitle = null;
 Object rawTypesObj = null; // may be JSONArray or String
 if (!isBlank(addProductsJson)) {
 try {
 JSONArray arr = new JSONArray(addProductsJson);
 if (arr.length() > 0) {
 JSONObject first = arr.optJSONObject(0);
 if (first != null) {
 jsonUom = first.optString("uom", null);
 jsonStdQty = first.optString("standard_quantity", null);
 jsonHs = first.optString("hscode", null);
 jsonCode = first.optString("product_code", null);
 jsonTitle = first.optString("product", null);
 rawTypesObj = first.opt("raw_material_type"); // may be array or string
 }
 }
 } catch (Exception jex) {
 LogUtil.warn(LOGGER, "Invalid JSON in c_add_products for id=" + appId + ": " + jex.getMessage());
 }
 }

 // 3) Final values (JSON overrides)
 String outSector = sectorId;
 String outSectorCode = (joinedSectorCode == null ? null : joinedSectorCode.trim());
 String outHscode = !isBlank(jsonHs) ? jsonHs : hscodeValue;
 String outTitle = !isBlank(jsonTitle) ? jsonTitle : requestedProductValue;
 String outUom = !isBlank(jsonUom) ? jsonUom : null;
 String outStdQty = !isBlank(jsonStdQty) ? jsonStdQty : null;
 String outProdCode = !isBlank(jsonCode) ? jsonCode : null;

 String outProdCodeConcat = (!isBlank(outSectorCode) && !isBlank(outProdCode))
 ? (outSectorCode + "-" + outProdCode)
 : outProdCode;

 LogUtil.info(LOGGER, "Final values → sector_code=" + outSectorCode + ", product_code(in)=" + outProdCode + ", product_code(out)=" + outProdCodeConcat);

 // 4) Upsert into products (with audit)
 Timestamp now = new Timestamp(System.currentTimeMillis());
 ins = con.prepareStatement(
 "INSERT INTO " + DST_TAB + " " +
 " (id, c_sector, c_sector_code, c_hscode, c_title, c_uom, c_standard_quantity, c_product_code, " +
 " dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName) " +
 "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_sector=VALUES(c_sector), " +
 " c_sector_code=VALUES(c_sector_code), " +
 " c_hscode=VALUES(c_hscode), " +
 " c_title=VALUES(c_title), " +
 " c_uom=VALUES(c_uom), " +
 " c_standard_quantity=VALUES(c_standard_quantity), " +
 " c_product_code=VALUES(c_product_code), " +
 " dateModified=VALUES(dateModified), " +
 " modifiedBy=VALUES(modifiedBy), " +
 " modifiedByName=VALUES(modifiedByName)"
 );

 int i = 1;
 setNullableString(ins, i++, idValue);
 setNullableString(ins, i++, outSector);
 setNullableString(ins, i++, outSectorCode);
 setNullableString(ins, i++, outHscode);
 setNullableString(ins, i++, outTitle);
 setNullableString(ins, i++, outUom);
 setNullableString(ins, i++, outStdQty);
 setNullableString(ins, i++, outProdCodeConcat);
 ins.setTimestamp(i++, now);
 ins.setTimestamp(i++, now);
 setNullableString(ins, i++, currEmail);
 setNullableString(ins, i++, (isBlank(ln)&&isBlank(fn)) ? null : ((isBlank(ln)?"":ln) + (isBlank(ln)||isBlank(fn)?"":" ") + (isBlank(fn)?"":fn)));
 setNullableString(ins, i++, currEmail);
 setNullableString(ins, i++, currFull);

 int rows = ins.executeUpdate();
 LogUtil.info(LOGGER, "UPSERT complete. Affected rows=" + rows + " (0 can be 'no change').");
 try { ins.close(); } catch (Exception ignore) {}

 // 5) Verify product write
 verifyRow(con, idValue);

 // 6) ---- RAW MATERIALS (Types + Items) ----
 JSONArray rawTypes = null;
 try {
 if (rawTypesObj instanceof JSONArray) {
 rawTypes = (JSONArray) rawTypesObj;
 } else if (rawTypesObj instanceof String) {
 String s = (String) rawTypesObj;
 if (!isBlank(s)) rawTypes = new JSONArray(s);
 }
 } catch (Exception jx) {
 LogUtil.warn(LOGGER, "raw_material_type not a valid JSON array; skipping. Reason: " + jx.getMessage());
 }

 if (rawTypes == null || rawTypes.length() == 0) {
 LogUtil.info(LOGGER, "No raw_material_type to process. Done.");
 LogUtil.info(LOGGER, "END. SUCCESS for id=" + appId);
 return "success";
 }

 // TYPE UPSERT: exclude c_uom, c_quantity, c_input_output_coefficient, c_waste_percentage
 String typeSQL =
 "INSERT INTO " + TYPE_TAB + " " +
 " (id, dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName," +
 " c_product_hscode, c_product, c_raw_material_type_code, c_product_code, c_title, c_sector) " +
 "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_product_hscode=VALUES(c_product_hscode)," +
 " c_product=VALUES(c_product)," +
 " c_raw_material_type_code=VALUES(c_raw_material_type_code)," +
 " c_product_code=VALUES(c_product_code)," +
 " c_title=VALUES(c_title)," +
 " c_sector=VALUES(c_sector)," +
 " dateModified=VALUES(dateModified)," +
 " modifiedBy=VALUES(modifiedBy), modifiedByName=VALUES(modifiedByName)";
 upType = con.prepareStatement(typeSQL);

 // ITEM UPSERT: includes per-item uom/qty/ioc/waste + item hscode
 String itemSQL =
 "INSERT INTO " + ITEM_TAB + " " +
 " (id, dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName," +
 " c_product, c_raw_material_type, c_hscode, c_raw_material_type_code, c_title, c_sector, c_input_code," +
 " c_uom, c_quantity, c_input_output_coefficient, c_waste_percentage) " +
 "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_hscode=VALUES(c_hscode), c_raw_material_type_code=VALUES(c_raw_material_type_code)," +
 " c_title=VALUES(c_title), c_sector=VALUES(c_sector), c_input_code=VALUES(c_input_code)," +
 " c_uom=VALUES(c_uom), c_quantity=VALUES(c_quantity)," +
 " c_input_output_coefficient=VALUES(c_input_output_coefficient)," +
 " c_waste_percentage=VALUES(c_waste_percentage)," +
 " dateModified=VALUES(dateModified), modifiedBy=VALUES(modifiedBy), modifiedByName=VALUES(modifiedByName)";
 upItem = con.prepareStatement(itemSQL);

 int typeUpserts = 0, itemUpserts = 0;

 for (int t = 0; t < rawTypes.length(); t++) {
 JSONObject tObj = rawTypes.optJSONObject(t);
 if (tObj == null) continue;

 String typeId = tObj.optString("RS_UNIQUE_VALUE", null);
 if (isBlank(typeId)) typeId = java.util.UUID.randomUUID().toString();

 String t_desc = tObj.optString("raw_material_type_description", null);
 String t_code = tObj.optString("raw_material_code", null);
 Object itemsObj = tObj.opt("raw_material_input"); // may be array or string

 // "<product_code>_<raw_material_type_code>" prefix
 String t_code_out;
 if (!isBlank(outProdCodeConcat) && !isBlank(t_code)) {
 t_code_out = outProdCodeConcat + "_" + t_code;
 } else if (!isBlank(outProdCodeConcat)) {
 t_code_out = outProdCodeConcat;
 } else {
 t_code_out = t_code;
 }

 // Upsert TYPE (note: excluded uom/qty/ioc/waste)
 int a = 1;
 setNullableString(upType, a++, typeId);
 upType.setTimestamp(a++, now);
 upType.setTimestamp(a++, now);
 setNullableString(upType, a++, currEmail);
 setNullableString(upType, a++, (isBlank(ln)&&isBlank(fn)) ? null : (ln + (isBlank(fn)?"":" ") + fn));
 setNullableString(upType, a++, currEmail);
 setNullableString(upType, a++, currFull);
 setNullableString(upType, a++, outHscode); // c_product_hscode
 setNullableString(upType, a++, idValue); // c_product (FK → product/application id)
 setNullableString(upType, a++, t_code_out); // c_raw_material_type_code
 setNullableString(upType, a++, outProdCodeConcat); // c_product_code
 setNullableString(upType, a++, t_desc); // c_title
 setNullableString(upType, a++, outSector); // c_sector
 typeUpserts += upType.executeUpdate();

 // Parse items array
 JSONArray itemsArr = null;
 try {
 if (itemsObj instanceof JSONArray) {
 itemsArr = (JSONArray) itemsObj;
 } else if (itemsObj instanceof String) {
 String s = (String) itemsObj;
 if (!isBlank(s)) itemsArr = new JSONArray(s);
 }
 } catch (Exception jx) {
 LogUtil.warn(LOGGER, "raw_material_input invalid for typeId=" + typeId + ": " + jx.getMessage());
 }
 if (itemsArr == null || itemsArr.length() == 0) continue;

 for (int k = 0; k < itemsArr.length(); k++) {
 JSONObject it = itemsArr.optJSONObject(k);
 if (it == null) continue;

 String itemId = it.optString("RS_UNIQUE_VALUE", null);
 if (isBlank(itemId)) itemId = java.util.UUID.randomUUID().toString();

 String i_desc = it.optString("input_description", null);
 String i_code = it.optString("input_code", null);
 String i_hs = it.optString("hscode", null);

 // Per-item fields
 String i_uom = it.optString("uom", null);
 String i_qty = it.optString("quantity", null);
 String i_ioc = it.optString("input_output_coefficient", null);
 String i_waste = it.optString("waste_percentage", null);

 // Build concatenated input code
 String itemInputCodeOut =
 (!isBlank(t_code_out) && !isBlank(i_code)) ? (t_code_out + "-" + i_code)
 : (!isBlank(t_code_out) ? t_code_out : i_code);

 int b = 1;
 setNullableString(upItem, b++, itemId);
 upItem.setTimestamp(b++, now);
 upItem.setTimestamp(b++, now);
 setNullableString(upItem, b++, currEmail);
 setNullableString(upItem, b++, (isBlank(ln)&&isBlank(fn)) ? null : (ln + (isBlank(fn)?"":" ") + fn));
 setNullableString(upItem, b++, currEmail);
 setNullableString(upItem, b++, currFull);
 setNullableString(upItem, b++, idValue); // c_product
 setNullableString(upItem, b++, typeId); // c_raw_material_type
 setNullableString(upItem, b++, i_hs); // c_hscode (item-level)
 setNullableString(upItem, b++, t_code_out); // c_raw_material_type_code (prefix)
 setNullableString(upItem, b++, i_desc); // c_title
 setNullableString(upItem, b++, outSector); // c_sector
 setNullableString(upItem, b++, itemInputCodeOut); // c_input_code
 setNullableString(upItem, b++, i_uom); // c_uom
 setNullableString(upItem, b++, i_qty); // c_quantity
 setNullableString(upItem, b++, i_ioc); // c_input_output_coefficient
 setNullableString(upItem, b++, i_waste); // c_waste_percentage

 itemUpserts += upItem.executeUpdate();

 LogUtil.info(LOGGER, "ITEM upsert id=" + itemId
 + " typeCode=" + t_code_out
 + " inputCodeRaw=" + i_code
 + " inputCodeOut=" + itemInputCodeOut
 + " uom=" + i_uom + " qty=" + i_qty + " ioc=" + i_ioc + " waste=" + i_waste);
 }
 }

 try { upType.close(); } catch (Exception ignore) {}
 try { upItem.close(); } catch (Exception ignore) {}

 LogUtil.info(LOGGER, "RAW MATERIALS written. types=" + typeUpserts + ", items=" + itemUpserts);
 LogUtil.info(LOGGER, "END. SUCCESS for id=" + appId);
 return "success";

} catch (Exception e) {
 LogUtil.error(LOGGER, e, "FAILED: " + e.getMessage());
 return "error";
} finally {
 try { if (rs != null) rs.close(); } catch (Exception ex) {}
 try { if (sel != null) sel.close(); } catch (Exception ex) {}
 try { if (ins != null) ins.close(); } catch (Exception ex) {}
 try { if (upType != null) upType.close(); } catch (Exception ex) {}
 try { if (upItem != null) upItem.close(); } catch (Exception ex) {}
 try { if (con != null) con.close(); } catch (Exception ex) {}
}
"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.json.JSONArray;
import org.json.JSONObject;

/* ========= CONFIG ========= */
final String LOGGER = "IOC-BeanShell";
final String REQ_TBL = "app_fd_eth_ioc_type_request";
final String PROD_TBL = "app_fd_eth_ioc_products";
final String TYPE_TBL = "app_fd_eth_ioc_raw_mat_type";
final String ITEM_TBL = "app_fd_eth_ioc_raw_mat_item";
final String HV_REQ_ID = "#form.eth_ioc_type_request.id#";

/* ========= HELPERS ========= */
String hv(String expr){
 try{
 String v = AppUtil.processHashVariable(expr, workflowAssignment, null, null);
 if (v == null) return null;
 v = v.trim();
 return (v.length()==0 || v.indexOf('#')>=0) ? null : v;
 }catch(Exception e){ return null; }
}
boolean blank(String s){ return s==null || s.trim().isEmpty() || "null".equalsIgnoreCase(s.trim()); }
void s(PreparedStatement ps, int idx, String v) throws Exception {
 if (blank(v)) ps.setNull(idx, Types.VARCHAR); else ps.setString(idx, v);
}
String rsg(ResultSet rs, String col){ try { return rs.getString(col); } catch(Exception e){ return null; } }

/* ========= MAIN ========= */
Connection con=null;
PreparedStatement psReq=null, psProd=null, upType=null, upItem=null;
ResultSet rsReq=null, rsProd=null;

try{
 String reqId = hv(HV_REQ_ID);
 if (reqId == null){ LogUtil.warn(LOGGER,"Request ID not resolved"); return "no-id"; }

 String userEmail = hv("#currentUser.email#");
 String fn = hv("#currentUser.firstName#");
 String ln = hv("#currentUser.lastName#");
 String userName = (blank(ln) && blank(fn)) ? null : ( (blank(ln)?"":ln) + (blank(ln)||blank(fn)?"":" ") + (blank(fn)?"":fn) );

 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 con.setAutoCommit(false);
 Timestamp now = new Timestamp(System.currentTimeMillis());

 LogUtil.info(LOGGER, "START type-request id=" + reqId);

 // 1) Read request row
 psReq = con.prepareStatement(
 "SELECT c_productId, c_add_raw_material_type FROM " + REQ_TBL + " WHERE id=?"
 );
 psReq.setString(1, reqId);
 rsReq = psReq.executeQuery();
 if (!rsReq.next()){ LogUtil.warn(LOGGER,"No request row id=" + reqId); con.rollback(); return "not-found"; }

 String productId = rsg(rsReq, "c_productId");
 String typesJson = rsg(rsReq, "c_add_raw_material_type");
 if (blank(typesJson)){ LogUtil.info(LOGGER,"No types JSON on request id="+reqId); con.commit(); return "no-types"; }

 // 2) Load product info (for sector, hs, product_code)
 String prodSector=null, prodHS=null, prodCode=null;
 if (!blank(productId)){
 psProd = con.prepareStatement(
 "SELECT c_sector, c_hscode, c_product_code FROM " + PROD_TBL + " WHERE id=?"
 );
 psProd.setString(1, productId);
 rsProd = psProd.executeQuery();
 if (rsProd.next()){
 prodSector = rsg(rsProd,"c_sector");
 prodHS = rsg(rsProd,"c_hscode");
 prodCode = rsg(rsProd,"c_product_code");
 }
 }
 LogUtil.info(LOGGER, "Product lookup → id="+productId+", sector="+prodSector+", hs="+prodHS+", product_code="+prodCode);
 if (blank(productId)){ LogUtil.warn(LOGGER,"productId missing in request; aborting to avoid orphans"); con.rollback(); return "no-product"; }

 // 3) Prepare UPSERTs
 String typeSQL =
 "INSERT INTO " + TYPE_TBL + " " +
 " (id, dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName," +
 " c_product_hscode, c_input_output_coefficient, c_product, c_uom, c_quantity," +
 " c_raw_material_type_code, c_waste_percentage, c_product_code, c_title, c_sector) " +
 "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_input_output_coefficient=VALUES(c_input_output_coefficient)," +
 " c_uom=VALUES(c_uom), c_quantity=VALUES(c_quantity)," +
 " c_raw_material_type_code=VALUES(c_raw_material_type_code)," +
 " c_waste_percentage=VALUES(c_waste_percentage)," +
 " c_product_code=VALUES(c_product_code), c_title=VALUES(c_title)," +
 " c_sector=VALUES(c_sector), dateModified=VALUES(dateModified)," +
 " modifiedBy=VALUES(modifiedBy), modifiedByName=VALUES(modifiedByName)";
 upType = con.prepareStatement(typeSQL);

 String itemSQL =
 "INSERT INTO " + ITEM_TBL + " " +
 " (id, dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName," +
 " c_product, c_raw_material_type, c_hscode, c_raw_material_type_code, c_title, c_sector, c_input_code) " +
 "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) " +
 "ON DUPLICATE KEY UPDATE " +
 " c_hscode=VALUES(c_hscode), c_raw_material_type_code=VALUES(c_raw_material_type_code)," +
 " c_title=VALUES(c_title), c_sector=VALUES(c_sector), c_input_code=VALUES(c_input_code)," +
 " dateModified=VALUES(dateModified), modifiedBy=VALUES(modifiedBy), modifiedByName=VALUES(modifiedByName)";
 upItem = con.prepareStatement(itemSQL);

 // 4) Parse types JSON
 JSONArray typesArr;
 try { typesArr = new JSONArray(typesJson); }
 catch(Exception ex){ LogUtil.error(LOGGER, ex, "Invalid JSON in c_add_raw_material_type"); con.rollback(); return "bad-json"; }

 int typeCount=0, itemCount=0;
 for (int t=0; t<typesArr.length(); t++){
 JSONObject to = typesArr.optJSONObject(t);
 if (to == null) continue;

 String typeId = to.optString("RS_UNIQUE_VALUE", null);
 if (blank(typeId)) typeId = java.util.UUID.randomUUID().toString();

 String tIOC = to.optString("input_output_coefficient", null);
 String tUom = to.optString("uom", null);
 String tQty = to.optString("quantity", null);
 String tWaste = to.optString("waste_percentage", null);
 String tTitle = to.optString("raw_material_type_description", null);
 String tCode = to.optString("raw_material_code", null);
 Object rawInObj = to.opt("raw_material_input"); // may be stringified JSON

 // Build sector-prefixed product code if your product codes already include sector (e.g., ELE-53)
 String typeCodeOut = null;
 if (!blank(prodCode) && !blank(tCode)) typeCodeOut = prodCode + "_" + tCode;
 else if (!blank(prodCode)) typeCodeOut = prodCode;
 else typeCodeOut = tCode;

 // UPSERT TYPE
 int a=1;
 s(upType, a++, typeId);
 upType.setTimestamp(a++, now);
 upType.setTimestamp(a++, now);
 s(upType, a++, userEmail);
 s(upType, a++, userName);
 s(upType, a++, userEmail);
 s(upType, a++, userName);
 s(upType, a++, prodHS); // c_product_hscode
 s(upType, a++, tIOC);
 s(upType, a++, productId); // c_product (FK)
 s(upType, a++, tUom);
 s(upType, a++, tQty);
 s(upType, a++, typeCodeOut); // concatenated type code
 s(upType, a++, tWaste);
 s(upType, a++, prodCode); // c_product_code from product
 s(upType, a++, tTitle);
 s(upType, a++, prodSector);
 typeCount += upType.executeUpdate();

 // Parse nested raw_material_input (string or array)
 JSONArray inputsArr = null;
 try {
 if (rawInObj instanceof JSONArray) {
 inputsArr = (JSONArray) rawInObj;
 } else if (rawInObj instanceof String) {
 String sjson = (String) rawInObj;
 if (!blank(sjson)) inputsArr = new JSONArray(sjson);
 }
 } catch(Exception ex) {
 LogUtil.warn(LOGGER, "raw_material_input invalid for typeId="+typeId+": "+ex.getMessage());
 }
 if (inputsArr == null || inputsArr.length()==0) continue;

 for (int i=0; i<inputsArr.length(); i++){
 JSONObject io = inputsArr.optJSONObject(i);
 if (io == null) continue;

 String itemId = io.optString("RS_UNIQUE_VALUE", null);
 if (blank(itemId)) itemId = java.util.UUID.randomUUID().toString();

 String inTitle = io.optString("input_description", null);
 String inCode = io.optString("input_code", null);
 String inHS = io.optString("hscode", null); // may be absent in your example

 String inputCodeOut =
 (!blank(typeCodeOut) && !blank(inCode)) ? (typeCodeOut + "_" + inCode)
 : (!blank(typeCodeOut) ? typeCodeOut : inCode);

 int p=1;
 s(upItem, p++, itemId);
 upItem.setTimestamp(p++, now);
 upItem.setTimestamp(p++, now);
 s(upItem, p++, userEmail);
 s(upItem, p++, userName);
 s(upItem, p++, userEmail);
 s(upItem, p++, userName);
 s(upItem, p++, productId); // c_product
 s(upItem, p++, typeId); // c_raw_material_type
 s(upItem, p++, inHS); // c_hscode
 s(upItem, p++, typeCodeOut); // c_raw_material_type_code (concatenated)
 s(upItem, p++, inTitle); // c_title
 s(upItem, p++, prodSector); // c_sector
 s(upItem, p++, inputCodeOut); // c_input_code
 itemCount += upItem.executeUpdate();

 LogUtil.info(LOGGER, "RMI upsert item="+itemId+" typeCode="+typeCodeOut+" inputCodeOut="+inputCodeOut);
 }
 }

 con.commit();
 LogUtil.info(LOGGER, "DONE. types upserted="+typeCount+", items upserted="+itemCount+", reqId="+reqId);
 return "success";

}catch(Exception e){
 try{ if(con!=null) con.rollback(); }catch(Exception ig){}
 LogUtil.error(LOGGER, e, "FAILED: " + e.getMessage());
 return "error";
}finally{
 try{ if(rsProd!=null) rsProd.close(); }catch(Exception ig){}
 try{ if(rsReq!=null) rsReq.close(); }catch(Exception ig){}
 try{ if(psProd!=null) psProd.close(); }catch(Exception ig){}
 try{ if(psReq!=null) psReq.close(); }catch(Exception ig){}
 try{ if(upType!=null) upType.close(); }catch(Exception ig){}
 try{ if(upItem!=null) upItem.close(); }catch(Exception ig){}
 try{ if(con!=null) con.close(); }catch(Exception ig){}
}
"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.json.JSONArray;
import org.json.JSONObject;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.plugin.base.PluginManager;

/* ========= CONFIG ========= */
final String LOGGER = "IOC-BeanShell";
final String REQ_TBL = "app_fd_eth_ioc_item_request";
final String TYPE_TBL = "app_fd_eth_ioc_raw_mat_type";
final String ITEM_TBL = "app_fd_eth_ioc_raw_mat_item";
final String HV_REQ_ID = "#form.eth_ioc_item_request.id#";

/* ========= HELPERS ========= */
String hv(String expr){
 try{
 String v = AppUtil.processHashVariable(expr, workflowAssignment, null, null);
 if (v == null) return null;
 v = v.trim();
 return (v.length()==0 || v.indexOf('#')>=0) ? null : v;
 }catch(Exception e){ return null; }
}
boolean blank(String s){ return s==null || s.trim().isEmpty() || "null".equalsIgnoreCase(s.trim()); }
void s(PreparedStatement ps, int idx, String v) throws Exception {
 if (blank(v)) ps.setNull(idx, Types.VARCHAR); else ps.setString(idx, v);
}
String rsg(ResultSet rs, String col){ try { return rs.getString(col); } catch(Exception e){ return null; } }

/* ========= MAIN ========= */
Connection con=null;
PreparedStatement psReq=null, psType=null, psUp=null;
ResultSet rsReq=null, rsType=null;

try{
 String reqId = hv(HV_REQ_ID);
 if (reqId == null){ LogUtil.warn(LOGGER,"Request ID not resolved"); return "no-id"; }

 String userEmail = hv("#currentUser.email#");
 String fn = hv("#currentUser.firstName#");
 String ln = hv("#currentUser.lastName#");
 String userName = (blank(ln) && blank(fn)) ? null : ( (blank(ln)?"":ln) + (blank(ln)||blank(fn)?"":" ") + (blank(fn)?"":fn) );

 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();
 con.setAutoCommit(false);
 Timestamp now = new Timestamp(System.currentTimeMillis());

 LogUtil.info(LOGGER, "START reqId=" + reqId);

 // 1) Read request row
 psReq = con.prepareStatement(
 "SELECT c_rawMaterialTypeId, c_addRawMaterialItem FROM " + REQ_TBL + " WHERE id=?"
 );
 psReq.setString(1, reqId);
 rsReq = psReq.executeQuery();
 if (!rsReq.next()){ LogUtil.warn(LOGGER,"No request row id=" + reqId); con.rollback(); return "not-found"; }

 String rawTypeId = rsg(rsReq, "c_rawMaterialTypeId");
 String itemsJson = rsg(rsReq, "c_addRawMaterialItem");

 if (blank(itemsJson)){ LogUtil.info(LOGGER,"Items JSON empty for id="+reqId); con.commit(); return "no-items"; }
 LogUtil.info(LOGGER, "rawTypeId=" + rawTypeId);
 LogUtil.info(LOGGER, "Items JSON length=" + itemsJson.length());

 // 2) Load type info (include raw-material-type code)
 String typeProduct=null, typeSector=null, typeProdCode=null, typeRawCode=null;
 if (!blank(rawTypeId)){
 psType = con.prepareStatement(
 "SELECT c_product, c_sector, c_product_code, c_raw_material_type_code " +
 "FROM " + TYPE_TBL + " WHERE id=?"
 );
 psType.setString(1, rawTypeId);
 rsType = psType.executeQuery();
 if (rsType.next()){
 typeProduct = rsg(rsType,"c_product");
 typeSector = rsg(rsType,"c_sector");
 typeProdCode = rsg(rsType,"c_product_code");
 typeRawCode = rsg(rsType,"c_raw_material_type_code"); // <-- added
 }
 }
 LogUtil.info(LOGGER, "Type lookup ? product=" + typeProduct + ", sector=" + typeSector
 + ", product_code=" + typeProdCode + ", raw_type_code=" + typeRawCode);

 // 3) Explicit UPSERT (no auto-detection)
 String sql = "INSERT INTO " + ITEM_TBL + " ("
 + " id, dateCreated, dateModified, createdBy, createdByName, modifiedBy, modifiedByName,"
 + " c_product, c_raw_material_type, c_hscode, c_raw_material_type_code, c_title, c_sector, c_input_code"
 + ") VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?) "
 + "ON DUPLICATE KEY UPDATE "
 + " dateModified=VALUES(dateModified),"
 + " modifiedBy=VALUES(modifiedBy),"
 + " modifiedByName=VALUES(modifiedByName),"
 + " c_product=VALUES(c_product),"
 + " c_raw_material_type=VALUES(c_raw_material_type),"
 + " c_hscode=VALUES(c_hscode),"
 + " c_raw_material_type_code=VALUES(c_raw_material_type_code),"
 + " c_title=VALUES(c_title),"
 + " c_sector=VALUES(c_sector),"
 + " c_input_code=VALUES(c_input_code)";
 psUp = con.prepareStatement(sql);
 LogUtil.info(LOGGER, "UPSERT SQL prepared.");

 // 4) Parse items and insert + collect titles
 JSONArray arr;
 try { arr = new JSONArray(itemsJson); }
 catch(Exception ex){ LogUtil.error(LOGGER, ex, "Invalid JSON in c_addRawMaterialItem"); con.rollback(); return "bad-json"; }

 LogUtil.info(LOGGER, "Items count=" + arr.length());
 int total=0, skipped=0;
 StringBuilder titlesSB = new StringBuilder();

 for (int i=0; i<arr.length(); i++){
 JSONObject it = arr.optJSONObject(i);
 if (it == null){ skipped++; continue; }

 String hscode = it.optString("hscode", null);
 String title = it.optString("input_description", null);
 String inputCode = it.optString("input_code", null);
 String rsuv = it.optString("RS_UNIQUE_VALUE", null);

 if (blank(hscode) && blank(title) && blank(inputCode)){
 skipped++; LogUtil.info(LOGGER,"Skip item "+i+" (empty)"); continue;
 }

 // Append title for Workflow variable
 if (!blank(title)){
 if (titlesSB.length() > 0) titlesSB.append(", ");
 titlesSB.append(title);
 }

 // c_raw_material_type_code stays = type.c_product_code (as before)
 String typeCode = typeProdCode; // may be null

 // NEW: c_input_code = product_code + "-" + raw_material_type_code + "-" + item.input_code (skip missing parts)
 StringBuilder icb = new StringBuilder();
 // if (!blank(typeProdCode)) icb.append(typeProdCode);
 if (!blank(typeRawCode)) { if (icb.length()>0) icb.append("-"); icb.append(typeRawCode); }
 if (!blank(inputCode)) { if (icb.length()>0) icb.append("-"); icb.append(inputCode); }
 String inputCodeOut = (icb.length()>0) ? icb.toString() : null;

 String itemId = reqId + "-" + ( !blank(rsuv) ? rsuv : String.valueOf(i+1) );

 int p=1;
 psUp.setString(p++, itemId); // id
 psUp.setTimestamp(p++, now); // dateCreated
 psUp.setTimestamp(p++, now); // dateModified
 s(psUp, p++, userEmail); // createdBy
 s(psUp, p++, userName); // createdByName
 s(psUp, p++, userEmail); // modifiedBy
 s(psUp, p++, userName); // modifiedByName
 s(psUp, p++, typeProduct); // c_product
 s(psUp, p++, rawTypeId); // c_raw_material_type
 s(psUp, p++, hscode); // c_hscode
 s(psUp, p++, typeCode); // c_raw_material_type_code (unchanged rule)
 s(psUp, p++, title); // c_title
 s(psUp, p++, typeSector); // c_sector
 s(psUp, p++, inputCodeOut); // c_input_code (NEW concatenation)

 int n = psUp.executeUpdate();
 total += n;
 LogUtil.info(LOGGER, "UPSERT itemId="+itemId+" → affected="+n
 +" (hs="+hscode+", title="+title+", typeCode="+typeCode+", inputCode="+inputCodeOut+")");
 }

 con.commit();
 LogUtil.info(LOGGER, "DONE. upserts="+total+", skipped="+skipped+", reqId="+reqId);

 // 5) Set workflow variable with all input titles (as a single string)
 try {
 PluginManager pluginManager = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
 WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
 String mergedTitles = titlesSB.toString(); // simple comma-separated list
 wm.activityVariable(workflowAssignment.getActivityId(), "merge_inputs_title", mergedTitles);
 LogUtil.info(LOGGER, "Workflow var 'merge_inputs_title' set to: " + mergedTitles);
 } catch (Exception wex) {
 LogUtil.warn(LOGGER, "Could not set workflow variable 'merge_inputs_title': " + wex.getMessage());
 }

 return "success";

}catch(Exception e){
 try{ if(con!=null) con.rollback(); }catch(Exception ig){}
 LogUtil.error(LOGGER, e, "FAILED: " + e.getMessage());
 return "error";
}finally{
 try{ if(rsType!=null) rsType.close(); }catch(Exception ig){}
 try{ if(rsReq!=null) rsReq.close(); }catch(Exception ig){}
 try{ if(psType!=null) psType.close(); }catch(Exception ig){}
 try{ if(psReq!=null) psReq.close(); }catch(Exception ig){}
 try{ if(psUp!=null) psUp.close(); }catch(Exception ig){}
 try{ if(con!=null) con.close(); }catch(Exception ig){}
}





